(function(){'use strict';
const root=document.getElementById('app'), $=id=>document.getElementById(id);
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid=()=>crypto.randomUUID();
const state={route:'home',view:'list',meta:{title:'',subject:'Hóa học',grade:'',topic:'',source_file:''},questions:[],examId:null,idx:0,exams:[],rooms:[],report:null,room:null,student:null,answers:{},current:0,marked:{},deadline:0,offset:0,submitting:false,studentSaved:true,loginEmail:'',authMode:'login',teacherRole:null,teacherEmail:''};
const label={mcq:'Nhiều lựa chọn',tf:'Đúng/Sai',short:'Trả lời ngắn',essay:'Tự luận'};
function toast(message,error=false){const n=$('toast');n.textContent=message;n.style.background=error?'#ad2525':'#103f74';n.style.display='block';setTimeout(()=>n.style.display='none',5500);}
const err=e=>{console.error(e);toast(e.message||String(e),true)};
function renderMath(){if(window.MathJax?.typesetPromise)window.MathJax.typesetPromise([root]).catch(()=>{});}
function route(to){state.route=to;document.querySelectorAll('nav [data-route]').forEach(x=>x.classList.toggle('active',x.dataset.route===to));render();}
function saveDraft(){try{localStorage.setItem('a4_edit_draft',JSON.stringify({meta:state.meta,questions:state.questions,examId:state.examId}));}catch(e){toast('Dung lượng lưu trình duyệt không đủ: cần xuất JSON sao lưu.',true)}}
function loadDraft(){try{const d=JSON.parse(localStorage.getItem('a4_edit_draft')||'null');if(d?.questions?.length){state.meta=d.meta;state.questions=d.questions;state.examId=d.examId;return true}}catch{}return false;}
const qTitle=(q)=>`PHẦN ${q.section} · Câu ${q.number||q.position}`;
function mediaHTML(srcs){return (srcs||[]).filter(s=>/^data:image\/(png|jpeg|gif|webp|svg\+xml);base64,/i.test(s)).map(s=>`<img class="inquestion" alt="Hình ảnh từ đề hoặc do giáo viên bổ sung" src="${E(s)}">`).join('');}
function qHTML(q,teacher=false){let s=`<div class="qa"><b>${E(qTitle(q))}.</b> ${E(q.body)}</div>${mediaHTML(q.media)}`;
 if(q.type==='mcq')s+=(q.options||[]).map(o=>`<div class="option ${teacher&&q.answer===o.id?'correct':''}"><b>${E(o.id)}.</b><div><span style="white-space:pre-wrap">${E(o.text)}</span>${mediaHTML(o.media|| (o.image?[o.image]:[]))}</div></div>`).join('');
 if(q.type==='tf')s+=(q.statements||[]).map(o=>`<div class="option"><b>${E(o.id)})</b><div>${E(o.text)}${mediaHTML(o.media)}</div>${teacher?`<strong style="color:#c32424">${q.answer?.[o.id]===true?'ĐÚNG':q.answer?.[o.id]===false?'SAI':'CHƯA CÓ ĐÁP ÁN'}</strong>`:''}</div>`).join('');
 if(teacher&&q.type==='short')s+=`<p style="color:#c32424"><b>Đáp án:</b> ${E(Array.isArray(q.answer)?q.answer.join(' / '):q.answer??'')}</p>`;
 if(teacher&&q.type==='essay')s+=`<div class="subtle"><b>Hướng dẫn chấm:</b> ${E(q.rubric||'Chưa nhập')}</div>`;
 return s;
}
function home(){root.innerHTML=`<div class="card"><h2>Phòng thi trực tuyến A4</h2><p>Quy trình: <b>Word gốc → Duyệt đề → Ngân hàng đề → Phòng thi online → Chấm bài → Excel</b>.</p><p class="muted">Giao diện này sử dụng dịch vụ Supabase thật khi được cấu hình. Không tự tạo dữ liệu hoặc kết nối giả.</p><div class="grid"><button class="primary" data-go="teacher">GIÁO VIÊN – QUẢN LÝ ĐỀ</button><button data-go="student">HỌC SINH – VÀO PHÒNG THI</button><button data-go="config">THIẾT LẬP KẾT NỐI</button></div></div><div class="card"><h3>Phạm vi triển khai</h3><p>Nhập <code>.docx</code> và phát hiện chữ đỏ; duyệt từng câu; lưu ngân hàng đề; tạo mã phòng; học sinh làm bài; chấm tự động tại máy chủ; giáo viên chấm tự luận, tải Excel.</p><div class="warning">Cần tài khoản Supabase đã triển khai SQL và Edge Function mới có thể dùng đa thiết bị. Nếu chưa cấu hình, có thể thử chức năng <b>nhập/duyệt Word và xuất JSON</b> ở chế độ giáo viên.</div><p class="tiny">Bản lưu A3 được bảo quản riêng trong gói mã nguồn, không đưa lên Vercel.</p></div>`;}
function config(){const c=API.getConfig();root.innerHTML=`<div class="card"><h2>Thiết lập kết nối Supabase</h2><p class="muted">Chỉ điền <b>Project URL</b> và <b>publishable (hoặc anon) key</b>. Không bao giờ dán secret key/service_role vào trình duyệt.</p><label class="field">Project URL</label><input id="cfgUrl" placeholder="https://xxxx.supabase.co" value="${E(c.url||'')}"><label class="field">Publishable / anon key (công khai)</label><input id="cfgKey" value="${E(c.key||'')}"><div class="row" style="margin-top:15px"><button class="primary" id="saveConfig">LƯU CẤU HÌNH</button><button id="healthCheck">KIỂM TRA MÁY CHỦ</button><button id="exportConfig">TẢI config.js CHO VERCEL</button></div><p class="tiny">Để học sinh truy cập từ điện thoại mà không cần tự nhập Supabase URL/Key, hãy tải <code>config.js</code> rồi thay tệp cùng tên trên website Vercel và triển khai lại. Chỉ dùng khóa công khai.</p><p id="configResult" class="tiny"></p></div>`;
 $('saveConfig').onclick=()=>{API.setConfig({url:$('cfgUrl').value,key:$('cfgKey').value});toast('Đã lưu cấu hình trên trình duyệt này')};
 $('exportConfig').onclick=()=>{
  const url=String($('cfgUrl').value||'').trim().replace(/\/$/,'');
  const key=String($('cfgKey').value||'').trim();
  if(!/^https:\/\/[^\s/]+\.supabase\.co$/i.test(url))return toast('Hãy nhập Project URL Supabase hợp lệ trước khi xuất config.js',true);
  if(!key||/sb_secret_|service_role/i.test(key))return toast('Chỉ được xuất publishable/anon key, KHÔNG sử dụng secret key!',true);
  const source='window.EDU_PUBLIC_CONFIG = '+JSON.stringify({url,key},null,2)+';\n';
  download(source,'config.js','text/javascript;charset=utf-8');
  toast('Đã tải config.js. Thay tệp này trên Vercel/GitHub và triển khai lại để mọi thiết bị cùng kết nối.');
 };
 $('healthCheck').onclick=async()=>{try{const v=await API.call('health');$('configResult').textContent='Đã kết nối: '+v.server_time;toast('Máy chủ đang hoạt động')}catch(e){$('configResult').textContent=e.message;err(e)}};
}
async function teacher(){
 if(!API.hasSession()){teacherLogin();return;}
 root.innerHTML='<div class="card"><p>Đang kiểm tra quyền tài khoản giáo viên...</p></div>';
 let profile;
 try{profile=await API.call('auth.status',{},true)}catch(e){err(e);teacherLogin();return;}
 state.teacherRole=profile.role;state.teacherEmail=profile.email;
 if(!['teacher','admin'].includes(profile.role)){
   root.innerHTML=`<div class="card" style="max-width:640px;margin:35px auto"><h2>Đã tạo tài khoản – đang chờ cấp quyền</h2><p>Email: <b>${E(profile.email)}</b></p><div class="warning">Tài khoản chỉ được tự cấp quyền <b>giáo viên</b> sau khi email đã được xác nhận và có lời mời hợp lệ từ quản trị viên. Vui lòng liên hệ quản trị viên để mời đúng email trên.</div><div class="row"><button id="pendingCheck">KIỂM TRA LẠI QUYỀN</button><button id="pendingLogout">ĐĂNG XUẤT</button></div></div>`;
   $('pendingCheck').onclick=()=>teacher();$('pendingLogout').onclick=()=>{API.signOut();teacherLogin()};return;
 }
 const menus=[['list','Ngân hàng đề'],['editor','Nhập & duyệt Word'],['rooms','Phòng thi'],['results','Bảng điểm']];
 if(profile.role==='admin')menus.push(['staff','Mời giáo viên']);
 if(state.view==='staff'&&profile.role!=='admin')state.view='list';
 root.innerHTML=`<div class="row between" style="margin-bottom:14px"><div class="row">${menus.map(([id,t])=>`<button data-view="${id}" class="${state.view===id?'primary':''}">${t}</button>`).join('')}</div><div class="row"><span class="tiny">${E(profile.email)} · ${profile.role==='admin'?'Quản trị viên':'Giáo viên'}</span><button id="logout" class="danger">Đăng xuất</button></div></div><div id="teacherView"></div>`;
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(state.view==='editor')syncEditor();state.view=b.dataset.view;teacher()});
 $('logout').onclick=()=>{API.signOut();state.teacherRole=null;toast('Đã đăng xuất');teacherLogin()};
 if(state.view==='list')bank();else if(state.view==='editor')editor();else if(state.view==='rooms')rooms();else if(state.view==='results')results();else if(state.view==='staff')teacherStaff();
}
function teacherLogin(){
 const mode=state.authMode||'login';
 if(mode==='signup'){
  root.innerHTML=`<div class="card" style="max-width:560px;margin:35px auto"><h2>Đăng ký tài khoản giáo viên</h2><p class="muted">Email đã được quản trị viên mời sẽ tự có quyền quản lý đề sau khi xác nhận email. Email chưa được mời có thể tạo tài khoản nhưng sẽ ở trạng thái chờ.</p><label class="field">Họ tên giáo viên</label><input id="signupName" autocomplete="name"><label class="field">Email</label><input id="signupEmail" type="email" autocomplete="email"><label class="field">Mật khẩu (ít nhất 10 ký tự)</label><input id="signupPassword" type="password" autocomplete="new-password"><label class="field">Nhập lại mật khẩu</label><input id="signupConfirm" type="password" autocomplete="new-password"><div class="row" style="margin-top:14px"><button class="primary" id="submitSignup">TẠO TÀI KHOẢN</button><button id="backLogin">ĐÃ CÓ TÀI KHOẢN</button></div><p class="tiny">Không lưu mật khẩu vào mã nguồn. Kiểm tra email do Supabase gửi để hoàn tất đăng ký.</p></div>`;
  $('submitSignup').onclick=async()=>{const password=$('signupPassword').value;if(password!==$('signupConfirm').value)return toast('Hai mật khẩu chưa trùng nhau',true);try{await API.signUp($('signupEmail').value,password,$('signupName').value);toast('Nếu đăng ký hợp lệ, email xác nhận sẽ được gửi. Hãy kiểm tra hộp thư.');state.authMode='login';teacherLogin()}catch(e){err(e)}};
  $('backLogin').onclick=()=>{state.authMode='login';teacherLogin()};return;
 }
 if(mode==='forgot'){
  root.innerHTML=`<div class="card" style="max-width:530px;margin:35px auto"><h2>Khôi phục mật khẩu giáo viên</h2><p class="muted">Nhập email để yêu cầu liên kết đặt lại mật khẩu.</p><label class="field">Email</label><input id="recoverEmail" type="email" autocomplete="email"><div class="row" style="margin-top:14px"><button class="primary" id="requestRecovery">GỬI EMAIL KHÔI PHỤC</button><button id="backLogin">Quay lại</button></div></div>`;
  $('requestRecovery').onclick=async()=>{try{await API.requestPasswordReset($('recoverEmail').value);toast('Nếu email đã đăng ký, hướng dẫn khôi phục sẽ được gửi.')}catch(e){err(e)}};
  $('backLogin').onclick=()=>{state.authMode='login';teacherLogin()};return;
 }
 root.innerHTML=`<div class="card" style="max-width:540px;margin:35px auto"><h2>Đăng nhập giáo viên – Quản lý đề</h2><p class="tiny">Dùng tài khoản Supabase của giáo viên. Tài khoản đăng ký mới cần xác nhận email và được quản trị viên mời. Passcode của bản thử nghiệm A3 không dùng cho bản online.</p><label class="field">Email</label><input id="loginEmail" type="email" autocomplete="username"><label class="field" for="loginPassword">Mật khẩu</label><div class="password-control"><input id="loginPassword" type="password" autocomplete="current-password" aria-describedby="passwordHelp"><button id="toggleLoginPassword" type="button" class="password-toggle" aria-controls="loginPassword" aria-pressed="false" title="Hiện mật khẩu">👁 Hiện mật khẩu</button></div><p id="passwordHelp" class="tiny" style="margin:5px 0 0">Nhấn “Hiện mật khẩu” để kiểm tra trước khi đăng nhập.</p><div class="row" style="margin-top:14px"><button class="primary" id="login">ĐĂNG NHẬP</button><button id="openSignup">TẠO TÀI KHOẢN GIÁO VIÊN</button><button id="openForgot">Quên mật khẩu?</button></div><div class="row" style="margin-top:14px"><button data-go="config">Kết nối Supabase</button><button id="offlineEdit">Mở bộ nhập Word chưa kết nối</button></div></div>`;
 $('toggleLoginPassword').onclick=()=>{const input=$('loginPassword'),button=$('toggleLoginPassword'),visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'🙈 Ẩn mật khẩu':'👁 Hiện mật khẩu';button.setAttribute('aria-pressed',String(visible));button.setAttribute('title',visible?'Ẩn mật khẩu':'Hiện mật khẩu');};
 $('login').onclick=async()=>{try{await API.signIn($('loginEmail').value,$('loginPassword').value);toast('Đã đăng nhập, đang kiểm tra quyền');state.view='list';teacher()}catch(e){err(e)}};
 $('openSignup').onclick=()=>{state.authMode='signup';teacherLogin()};
 $('openForgot').onclick=()=>{state.authMode='forgot';teacherLogin()};
 $('offlineEdit').onclick=()=>{state.route='offlineEditor';render()};
}
async function teacherStaff(){
 const v=$('teacherView');if(!v)return;
 v.innerHTML=`<div class="card"><h2>Mời giáo viên – tự động cấp quyền sau khi xác nhận email</h2><p class="muted">Chỉ quản trị viên có quyền gửi lời mời. Người được mời truy cập website Vercel để đăng ký bằng đúng email, xác nhận email và tự động được cấp quyền quản lý đề của mình.</p><label class="field">Email giáo viên muốn mời *</label><input id="inviteEmail" type="email" autocomplete="off" placeholder="giaovien@truong.edu.vn"><label class="field">Họ tên giáo viên (tùy chọn)</label><input id="inviteName" autocomplete="off"><div class="row" style="margin-top:13px"><button class="primary" id="inviteSave">CẤP LỜI MỜI</button><button id="inviteCopy">SAO CHÉP LINK ĐĂNG KÝ</button><button id="inviteRefresh">LÀM MỚI</button></div><p class="tiny">Lời mời có hiệu lực 30 ngày. Việc này tạo quyền trong cơ sở dữ liệu, không tự gửi email mời. Supabase sẽ gửi email xác nhận khi giáo viên tự đăng ký.</p><div id="inviteRows" class="tablewrap" style="margin-top:16px"></div></div>`;
 $('inviteSave').onclick=async()=>{try{const r=await API.call('admin.inviteTeacher',{email:$('inviteEmail').value,display_name:$('inviteName').value},true);toast(r.activated?'Đã cấp quyền cho tài khoản đã xác minh email':'Đã tạo lời mời, giáo viên có thể đăng ký và xác minh email');teacherStaff()}catch(e){err(e)}};
 $('inviteCopy').onclick=async()=>{const url=new URL(location.href);url.searchParams.delete('room');url.searchParams.set('teacher','register');try{await navigator.clipboard.writeText(url.toString());toast('Đã sao chép đường dẫn đăng ký')}catch(e){err(e)}};
 $('inviteRefresh').onclick=()=>teacherStaff();
 try{const r=await API.call('admin.teacherInvites',{},true);const rows=r.invites||[];
  $('inviteRows').innerHTML=rows.length?`<table><thead><tr><th>Email</th><th>Họ tên</th><th>Trạng thái</th><th>Hết hạn</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${E(x.email)}</td><td>${E(x.display_name)}</td><td>${x.claimed_at?'Đã kích hoạt':x.active&&new Date(x.expires_at)>new Date()?'Đang chờ đăng ký':'Hết hạn'}</td><td>${E(new Date(x.expires_at).toLocaleDateString('vi-VN'))}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Chưa có lời mời nào.</p>';
 }catch(e){err(e)}
}
function resetPassword(){
 if(!API.hasSession()){state.authMode='forgot';teacherLogin();return;}
 root.innerHTML=`<div class="card" style="max-width:550px;margin:35px auto"><h2>Đặt mật khẩu giáo viên mới</h2><p>Liên kết khôi phục đã được xác nhận. Nhập mật khẩu mới ít nhất 10 ký tự.</p><label class="field">Mật khẩu mới</label><input type="password" id="newPassword" autocomplete="new-password"><label class="field">Nhập lại</label><input type="password" id="newPasswordConfirm" autocomplete="new-password"><div class="row" style="margin-top:12px"><button class="primary" id="savePassword">LƯU MẬT KHẨU MỚI</button></div></div>`;
 $('savePassword').onclick=async()=>{const pw=$('newPassword').value;if(pw!==$('newPasswordConfirm').value)return toast('Mật khẩu nhập lại chưa trùng nhau',true);try{await API.changePassword(pw);API.signOut();toast('Đã cập nhật mật khẩu. Đăng nhập lại.');state.authMode='login';route('teacher')}catch(e){err(e)}};
}
function bank(){const v=$('teacherView');v.innerHTML=`<div class="card"><div class="row between"><h2>Ngân hàng đề thi</h2><div class="row"><button id="refreshExams">Làm mới</button><button class="primary" id="newExam">+ Nhập đề Word</button></div></div><input id="examFilter" placeholder="Tìm theo tên đề, môn học, lớp, chủ đề"><div id="examRows" class="list" style="margin-top:12px"></div></div>`;
 $('refreshExams').onclick=loadExams;$('newExam').onclick=()=>{newExam();state.view='editor';teacher()};$('examFilter').oninput=drawExams;drawExams();if(!state.exams.length)loadExams();
}
async function loadExams(){try{state.exams=(await API.call('teacher.exams',{},true)).exams;drawExams()}catch(e){err(e)}}
function drawExams(){const v=$('examRows');if(!v)return;const f=($('examFilter')?.value||'').toLowerCase();v.innerHTML=(state.exams||[]).filter(x=>(x.title+' '+x.subject+' '+x.grade+' '+x.topic).toLowerCase().includes(f)).map(x=>`<div class="item"><div class="row between"><div><b>${E(x.title)}</b><div class="tiny">${E(x.subject)} · Lớp ${E(x.grade||'—')} · ${E(x.topic||'Không ghi chủ đề')} · Phiên bản ${E(x.revision)}</div></div><div class="row"><button data-load="${x.id}">Mở / chỉnh sửa</button><button data-copy="${x.id}">Nhân bản</button><button data-history="${x.id}">Lịch sử</button></div></div></div>`).join('')||'<p class="muted">Chưa có đề thi. Chọn Nhập đề Word.</p>';
 v.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>loadExam(b.dataset.load));v.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>loadExam(b.dataset.copy,true));}
async function showHistory(id){try{const h=await API.call('teacher.history',{exam_id:id},true);let text='Lịch sử phiên bản: '+h.versions.map(v=>'V'+v.revision+' ('+new Date(v.created_at).toLocaleString('vi-VN')+')').join(' | ');if(!h.versions.length)return toast('Chưa có phiên bản');const rev=prompt(text+'\nNhập số phiên bản muốn phục hồi (tạo phiên bản mới):');if(rev===null)return;const n=Number(rev);if(!h.versions.some(v=>v.revision===n))throw Error('Số phiên bản không hợp lệ');if(!confirm('Khôi phục bản V'+n+'? Hệ thống sẽ tạo phiên bản mới, không xóa lịch sử.'))return;await API.call('teacher.restore',{exam_id:id,revision:n},true);await loadExams();toast('Đã khôi phục thành một phiên bản mới');}catch(e){err(e)}}
async function loadExam(id,copy=false){try{const r=await API.call('teacher.get',{exam_id:id},true);state.meta={title:r.exam.title+(copy?' - Bản sao':''),subject:r.exam.subject,grade:r.exam.grade,topic:r.exam.topic,source_file:r.exam.source_file};
 state.questions=structuredClone(r.questions).map(q=>({...q, ...(copy?{id:uuid()}:{}),number:q.position}));state.examId=copy?null:id;state.idx=0;saveDraft();state.view='editor';teacher();}catch(e){err(e)}}
function newExam(){state.examId=null;state.questions=[];state.idx=0;state.meta={title:'',subject:'Hóa học',grade:'',topic:'',source_file:''};saveDraft()}
function editor(){const v=state.route==='offlineEditor'?root:$('teacherView');
 v.innerHTML=`<div class="card"><div class="row between"><h2>Nhập đề & kiểm duyệt Word</h2><span class="pill">${state.questions.length} câu</span></div><div class="grid"><div><label class="field">Tên kỳ thi / đề thi</label><input id="mTitle" value="${E(state.meta.title)}"></div><div><label class="field">Môn học</label><input id="mSubject" value="${E(state.meta.subject)}"></div><div><label class="field">Lớp</label><input id="mGrade" value="${E(state.meta.grade)}"></div><div><label class="field">Chủ đề</label><input id="mTopic" value="${E(state.meta.topic)}"></div></div><hr class="sep"><div class="row"><label class="btn">Nhập file Word .docx <input id="wordFile" type="file" accept=".docx" style="max-width:235px"></label><label class="btn">Nhập JSON <input id="jsonFile" type="file" accept=".json" style="max-width:200px"></label><button id="exportJSON">Xuất JSON sao lưu</button><button class="primary" id="saveExam" ${state.route==='offlineEditor'?'disabled':''}>LƯU NGÂN HÀNG ĐỀ</button></div><div class="tiny" style="margin-top:8px">Chỉ sử dụng dữ liệu đề gốc. Đáp án PHẦN I/II đọc từ chữ đỏ; PHẦN III từ “Đáp án:”. Công thức WMF sẽ được đánh dấu cần khắc phục trước khi duyệt.</div><div id="importReport"></div></div><div id="editArea"></div>`;
 for(const id of ['mTitle','mSubject','mGrade','mTopic'])$(id).onchange=()=>{metaSync();saveDraft()};
 $('wordFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const r=await WordReader.readWord(f);state.meta=r.meta;state.sourceFile=f;state.questions=r.questions;state.examId=null;state.idx=0;saveDraft();editor();$('importReport').innerHTML=`<div class="good">Đã đọc ${r.report.total} câu: I: ${r.report.sections.I}, II: ${r.report.sections.II}, III: ${r.report.sections.III}, IV: ${r.report.sections.IV}. Có ${r.report.warningCount} cảnh báo cần xử lý.</div>`;toast('Đã nhận diện đề Word. Hãy kiểm tra từng câu trước khi phê duyệt.');}catch(x){err(x)}};
 $('jsonFile').onchange=async e=>{try{const j=JSON.parse(await e.target.files[0].text());if(!Array.isArray(j.questions)||!j.questions.length)throw Error('JSON không có danh sách câu hỏi');state.questions=j.questions.map((x,i)=>({...x,id:x.id||uuid(),position:i+1,approved:!!x.approved,issues:x.issues||[]}));state.meta=j.meta||state.meta;state.examId=null;state.idx=0;saveDraft();editor()}catch(x){err(x)}};
 $('exportJSON').onclick=()=>{metaSync();syncEditor();download(JSON.stringify({meta:state.meta,questions:state.questions},null,2),'DE_THI_A4.json','application/json')};
 $('saveExam').onclick=saveExam;drawEditor();
}
function metaSync(){state.meta={...state.meta,title:$('mTitle')?.value||state.meta.title,subject:$('mSubject')?.value||state.meta.subject,grade:$('mGrade')?.value||state.meta.grade,topic:$('mTopic')?.value||state.meta.topic}}
function validate(q){const issues=[];if(!q.body?.trim())issues.push('Thiếu câu hỏi');if(!Number.isFinite(+q.points)||+q.points<=0)issues.push('Chưa nhập điểm');if(q.issues?.length)issues.push('Còn cảnh báo nguồn');
 if(q.type==='mcq'){if(q.options.length<2||q.options.some(x=>!x.text?.trim() && !(x.media?.length)))issues.push('Thiếu phương án');if(!q.options.some(o=>o.id===q.answer))issues.push('Chưa có đáp án')}
 if(q.type==='tf'){if(!q.statements.length||q.statements.some(x=>!x.text?.trim()))issues.push('Thiếu ý Đ/S');if(q.statements.some(s=>typeof q.answer?.[s.id]!=='boolean'))issues.push('Thiếu đáp án từng ý');if(!q.grading?.mode)issues.push('Thiếu quy tắc chấm');if(q.grading?.mode==='score_by_correct_count')for(let i=0;i<=q.statements.length;i++)if(!Number.isFinite(+q.grading?.scores?.[i]))issues.push('Thiếu mức điểm cho '+i+' ý')}
 if(q.type==='short'&&(q.answer===null||q.answer===undefined||String(q.answer).trim()===''))issues.push('Thiếu đáp án');if(q.type==='essay'&&!q.rubric?.trim())issues.push('Thiếu hướng dẫn chấm');return issues;}
function drawEditor(){const v=$('editArea');if(!v)return;const qs=state.questions;
 if(!qs.length){v.innerHTML='<div class="card">Chưa có đề. Chọn tệp Word .docx hoặc JSON để nhập câu hỏi thật.</div>';return}
 const q=qs[state.idx]||qs[0];v.innerHTML=`<div class="columns"><div><div class="card"><div class="row between"><h3>${E(qTitle(q))} — ${E(label[q.type])}</h3><span class="pill">${state.idx+1}/${qs.length}</span></div><label class="field">Nội dung câu hỏi</label><textarea id="editBody">${E(q.body)}</textarea><label class="field">Điểm (bắt buộc giáo viên xác nhận)</label><input type="number" min="0.01" step="0.01" id="editPoints" value="${E(q.points)}"><label class="field">Dạng câu</label><select id="editType">${Object.keys(label).map(k=>`<option value="${k}" ${k===q.type?'selected':''}>${label[k]}</option>`).join('')}</select><div id="specificForm" style="margin-top:15px">${specificHTML(q)}</div><hr class="sep"><label class="field">Bổ sung ảnh gốc dạng PNG / JPEG (có thể nhiều ảnh)</label><input id="images" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple><div>${mediaHTML(q.media)} </div><div id="issues">${issueHTML(q)}</div><label class="option"><input id="approve" type="checkbox" ${q.approved?'checked':''}> <b>Tôi đã đối chiếu và duyệt chính xác câu hỏi, đáp án, biểu điểm</b></label><div class="row"><button id="prevQ" ${state.idx===0?'disabled':''}>← Câu trước</button><button id="nextQ" ${state.idx===qs.length-1?'disabled':''}>Câu tiếp →</button><button id="addQ">+ Thêm câu trống</button></div></div></div><aside><div class="card"><h3>Toàn bộ câu hỏi</h3><div class="quiz-nav">${qs.map((x,i)=>`<button class="q-number ${i===state.idx?'active':''} ${x.approved?'done':''}" data-toq="${i}" title="PHẦN ${x.section}, ${label[x.type]}">${i+1}</button>`).join('')}</div><p class="tiny">Đã duyệt: ${qs.filter(x=>x.approved).length} / ${qs.length}</p><hr class="sep"><h3>Xem trước</h3><div id="livePreview">${qHTML(q,true)}</div></div></aside></div>`;
 $('prevQ').onclick=()=>changeQ(-1);$('nextQ').onclick=()=>changeQ(1);v.querySelectorAll('[data-toq]').forEach(b=>b.onclick=()=>{syncEditor();state.idx=+b.dataset.toq;drawEditor()});
 $('editType').onchange=()=>{syncEditor();q.type=$('editType').value;q.approved=false;drawEditor()};
 $('approve').onchange=e=>{syncEditor();const v=validate(q);if(e.target.checked&&v.length){e.target.checked=false;q.approved=false;toast('Không thể duyệt: '+v.join('; '),true)}else q.approved=e.target.checked;saveDraft();drawEditor()};
 $('images').onchange=async e=>{for(const file of e.target.files)q.media.push(await toDataURL(file));q.approved=false;saveDraft();drawEditor()};
 $('addQ').onclick=()=>{syncEditor();if(!confirm('Thêm câu trống để giáo viên nhập nội dung thật?'))return;const n={id:uuid(),position:qs.length+1,number:1,section:'IV',type:'essay',body:'',options:[],statements:[],media:[],points:0,answer:null,grading:{},rubric:'',approved:false,issues:[]};qs.push(n);state.idx=qs.length-1;drawEditor()};
 v.querySelectorAll('[data-clearwarn]').forEach(b=>b.onclick=()=>{syncEditor();const i=+b.dataset.clearwarn;const warning=q.issues[i];const requiresMedia=/WMF|EMF|công thức|ảnh|image/i.test(warning);
   const hasMedia=(q.media||[]).length || q.options?.some(o=>o.media?.length);
   if(!$('verifiedWord')?.checked){toast('Cần đánh dấu đã đối chiếu Word gốc',true);return}
   if(requiresMedia&&!hasMedia){toast('Cảnh báo ảnh/công thức yêu cầu bổ sung tệp PNG/JPEG gốc trước khi xác nhận',true);return}
   if(confirm('Xác nhận đã khắc phục và đối chiếu trực tiếp với đề gốc?')){q.issues.splice(i,1);q.approved=false;saveDraft();drawEditor()}
 });
 v.querySelectorAll('#editBody,#editPoints,[data-opt],[data-statement],#editAnswer,[data-tf],#tfMode,#tfScores,#shortAnswer,#shortTol,#rubric').forEach(el=>el.addEventListener('change',()=>{syncEditor();const pv=$('livePreview');if(pv)pv.innerHTML=qHTML(q,true);if(q.approved){q.approved=false;const a=$('approve');if(a)a.checked=false;}saveDraft()}));
 v.querySelectorAll('[data-option-image]').forEach(inp=>inp.onchange=async e=>{syncEditor();const id=inp.dataset.optionImage;const o=q.options.find(x=>x.id===id);if(o){o.media=o.media||[];for(const f of inp.files)o.media.push(await toDataURL(f));q.approved=false;saveDraft();drawEditor()}});
}
function issueHTML(q){return `<h3 style="margin-top:17px">Cảnh báo nguồn: ${(q.issues||[]).length}</h3>${(q.issues||[]).map((x,i)=>`<div class="warning">${E(x)} <button data-clearwarn="${i}" class="danger">Đã khắc phục</button></div>`).join('')}${q.issues?.length?'<label class="tiny"><input id="verifiedWord" type="checkbox"> Tôi đã so sánh nội dung với tệp Word gốc và bổ sung tài nguyên thật.</label>':''}`}
function specificHTML(q){
 if(q.type==='mcq')return `<h3>Phương án (đáp án đúng hiển thị đỏ ở chế độ giáo viên)</h3>${(q.options||[]).map(o=>`<label class="field">${E(o.id)}.</label><textarea data-opt="${E(o.id)}" rows="2">${E(o.text)}</textarea><label class="tiny">Ảnh cho phương án ${E(o.id)} <input type="file" data-option-image="${E(o.id)}" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label>${mediaHTML(o.media)}`).join('')}<label class="field">Đáp án đúng</label><select id="editAnswer"><option value="">Chưa xác định</option>${(q.options||[]).map(o=>`<option value="${E(o.id)}" ${q.answer===o.id?'selected':''}>${E(o.id)}</option>`).join('')}</select>`;
 if(q.type==='tf')return `<h3>Các nhận định và đáp án Đúng/Sai</h3>${(q.statements||[]).map(s=>`<label class="field">Ý ${E(s.id)}</label><textarea data-statement="${E(s.id)}" rows="2">${E(s.text)}</textarea><select data-tf="${E(s.id)}"><option value="" ${typeof q.answer?.[s.id]!=='boolean'?'selected':''}>Chưa xác định</option><option value="true" ${q.answer?.[s.id]===true?'selected':''}>Đúng</option><option value="false" ${q.answer?.[s.id]===false?'selected':''}>Sai</option></select>`).join('')}<label class="field">Quy tắc chấm</label><select id="tfMode"><option value="">Chọn theo hướng dẫn chấm</option>${[['all_or_nothing','Đúng toàn bộ mới được điểm'],['per_statement','Chia đều điểm từng ý'],['score_by_correct_count','Bảng điểm theo số ý đúng']].map(([v,t])=>`<option value="${v}" ${q.grading?.mode===v?'selected':''}>${t}</option>`).join('')}</select><label class="field">Bảng điểm 0..n ý đúng (nếu chọn bảng điểm)</label><input id="tfScores" placeholder="0;0.1;0.25;0.5;1" value="${E(q.grading?.scores?Object.keys(q.grading.scores).sort((a,b)=>+a-+b).map(k=>q.grading.scores[k]).join(';'):'')}"><p class="tiny">Chỉ nhập bảng điểm thật từ hướng dẫn chấm, không tự chia điểm.</p>`;
 if(q.type==='short')return `<label class="field">Đáp án:</label><input id="shortAnswer" value="${E(q.answer??'')}"><label class="field">Sai số số học cho phép (để trống nếu so khớp chính xác)</label><input id="shortTol" type="number" step="any" min="0" value="${E(q.grading?.tolerance??'')}">`;
 return `<label class="field">Hướng dẫn chấm / rubric</label><textarea id="rubric" rows="6">${E(q.rubric||'')}</textarea>`;
}
function syncEditor(){if(!$('editBody')||!state.questions.length)return;const q=state.questions[state.idx];const before=JSON.stringify({body:q.body,points:q.points,options:q.options,statements:q.statements,answer:q.answer,grading:q.grading,rubric:q.rubric});q.body=$('editBody').value;q.points=Number($('editPoints').value);const type=$('editType').value;
 if(type===q.type){if(type==='mcq'){q.options.forEach(o=>{const e=root.querySelector(`[data-opt="${o.id}"]`);if(e)o.text=e.value});q.answer=$('editAnswer')?.value||null}
 if(type==='tf'){q.statements.forEach(s=>{const t=root.querySelector(`[data-statement="${s.id}"]`),a=root.querySelector(`[data-tf="${s.id}"]`);if(t)s.text=t.value;q.answer=q.answer||{};if(a)q.answer[s.id]=a.value===''?null:a.value==='true'});q.grading=q.grading||{};q.grading.mode=$('tfMode')?.value||'';
 const score=$('tfScores')?.value.trim();if(score){const arr=score.split(';').map(s=>+s.trim());q.grading.scores=Object.fromEntries(arr.map((x,i)=>[String(i),x]));}}
 if(type==='short'){q.answer=$('shortAnswer')?.value||'';q.grading=q.grading||{};const tol=$('shortTol')?.value;q.grading.tolerance=tol===''?null:Number(tol)}
 if(type==='essay')q.rubric=$('rubric')?.value||'';}
 const after=JSON.stringify({body:q.body,points:q.points,options:q.options,statements:q.statements,answer:q.answer,grading:q.grading,rubric:q.rubric});if(before!==after)q.approved=false;metaSync();saveDraft();}
function changeQ(d){syncEditor();state.idx=Math.max(0,Math.min(state.questions.length-1,state.idx+d));drawEditor()}
async function saveExam(){try{syncEditor();metaSync();const issues=state.questions.flatMap((q,i)=>q.approved?validate(q).map(s=>`Câu ${i+1}: ${s}`):[]);if(issues.length)throw Error(issues.slice(0,4).join('; '));const r=await API.call('teacher.save',{exam_id:state.examId,meta:state.meta,questions:state.questions},true);state.examId=r.exam_id;if(state.sourceFile){try{const bytes=new Uint8Array(await state.sourceFile.arrayBuffer());let bin='';for(const b of bytes)bin+=String.fromCharCode(b);await API.call('teacher.source.upload',{exam_id:r.exam_id,name:state.sourceFile.name,base64:btoa(bin)},true);state.sourceFile=null;}catch(ex){toast('Đề đã lưu nhưng lưu Word gốc chưa thành công: '+ex.message,true)}}toast('Đã lưu vào ngân hàng đề, dữ liệu lưu trên máy chủ');await loadExams();}catch(e){err(e)}}
function localEditor(){root.innerHTML='';editor();}
function toDataURL(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(fr.error);fr.readAsDataURL(file)})}
function download(text,name,mime){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:mime}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),8000)}
async function rooms(){const v=$('teacherView');v.innerHTML=`<div class="card"><h2>Tạo và quản lý phòng thi online</h2><div class="grid"><div><label class="field">Chọn đề đã lưu</label><select id="roomExam"><option value="">-- Chọn đề --</option>${state.exams.map(x=>`<option value="${x.id}">${E(x.title)}</option>`).join('')}</select></div><div><label class="field">Thời lượng bài thi (phút)</label><input id="roomDuration" type="number" min="1" max="300" value="45"></div><div><label class="field">Bắt đầu (giờ địa phương)</label><input id="roomStart" type="datetime-local"></div><div><label class="field">Kết thúc mở phòng (giờ địa phương)</label><input id="roomEnd" type="datetime-local"></div></div><div class="row" style="margin-top:15px"><button class="primary" id="createRoom">TẠO PHÒNG THI</button><button id="refreshRooms">Làm mới danh sách</button></div><p class="tiny">Mọi câu phải được duyệt, có đáp án và biểu điểm trước khi mở phòng. Thời hạn mỗi học sinh do máy chủ quản lý.</p><div id="roomCreateResult"></div></div><div class="card"><h3>Phòng thi đã tạo</h3><div id="roomRows" class="list"></div></div>`;
 if(!state.exams.length)loadExams();
 const start=new Date(),end=new Date(Date.now()+24*60*60*1000);function inpDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
 $('roomStart').value=inpDate(start);$('roomEnd').value=inpDate(end);
 $('createRoom').onclick=async()=>{try{const r=await API.call('teacher.createRoom',{exam_id:$('roomExam').value,duration_minutes:Number($('roomDuration').value),starts_at:new Date($('roomStart').value).toISOString(),ends_at:new Date($('roomEnd').value).toISOString()},true);
   state.rooms.unshift({...r.room});toast('Đã tạo phòng thi trên máy chủ');drawRooms();}catch(e){err(e)}};
 $('refreshRooms').onclick=loadRooms;drawRooms();loadRooms();
}
async function loadRooms(){try{state.rooms=(await API.call('teacher.rooms',{},true)).rooms;drawRooms()}catch(e){err(e)}}
function roomLink(code){return location.protocol==='file:'?'':location.origin+location.pathname+'?room='+encodeURIComponent(code)}
function drawRooms(){const v=$('roomRows');if(!v)return;v.innerHTML=state.rooms.map(r=>{const link=roomLink(r.code);return `<div class="item"><div class="row between"><div><strong>${E(r.exams?.title||'Phòng thi')}</strong><div class="tiny">Mã phòng <b>${E(r.code)}</b> · ${E(r.duration_minutes)} phút · ${r.active?'Đang mở':'Đã đóng'}</div><div class="tiny">Từ ${E(new Date(r.starts_at).toLocaleString('vi-VN'))} đến ${E(new Date(r.ends_at).toLocaleString('vi-VN'))}</div></div><div class="row"><button data-copylink="${E(link)}" ${link?'':'disabled'}>Sao chép link</button><button data-qr="${r.id}" ${link?'':'disabled'}>Hiển thị QR</button><button data-report="${r.id}">Xem bài nộp</button>${r.active?`<button class="danger" data-close="${r.id}">Đóng phòng</button>`:''}</div></div><div id="qr-${r.id}"></div></div>`}).join('')||'<p>Chưa tạo phòng thi.</p>';
 v.querySelectorAll('[data-copylink]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copylink);toast('Đã sao chép đường link phòng thi')}catch(e){err(e)}});
 v.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{state.selectedRoom=b.dataset.report;state.view='results';teacher()});
 v.querySelectorAll('[data-close]').forEach(b=>b.onclick=async()=>{if(!confirm('Đóng phòng ngay? Học sinh mới không thể tham gia.'))return;try{await API.call('teacher.closeRoom',{room_id:b.dataset.close},true);await loadRooms()}catch(e){err(e)}});
 v.querySelectorAll('[data-qr]').forEach(b=>b.onclick=async()=>{const room=state.rooms.find(r=>r.id===b.dataset.qr);if(!room)return;try{const qr=await API.call('teacher.qr',{room_id:room.id,link:roomLink(room.code)},true);const output=$('qr-'+room.id);const img=document.createElement('img');img.alt='Mã QR vào phòng thi';img.width=210;img.height=210;img.src='data:image/svg+xml;base64,'+qr.svg_base64;output.innerHTML='';output.append(img)}catch(e){err(e)}});
}
async function results(){const v=$('teacherView');v.innerHTML=`<div class="card"><div class="row between"><h2>Kết quả và chấm tự luận</h2><button id="getResults" class="primary">Tải bảng điểm</button></div><label class="field">Chọn phòng thi</label><select id="reportRoom"><option value="">-- Chọn phòng --</option>${state.rooms.map(r=>`<option value="${r.id}" ${r.id===state.selectedRoom?'selected':''}>${E(r.code)} · ${E(r.exams?.title||'')}</option>`).join('')}</select><div id="reportTable" style="margin-top:18px"></div></div>`;
 $('getResults').onclick=async()=>{state.selectedRoom=$('reportRoom').value;if(!state.selectedRoom)return toast('Hãy chọn phòng thi',true);try{state.report=await API.call('teacher.results',{room_id:state.selectedRoom},true);drawResults()}catch(e){err(e)}};
 if(!state.rooms.length)loadRooms();else if(state.selectedRoom)$('getResults').click();
}
function drawResults(){const v=$('reportTable'),r=state.report;if(!v||!r)return;const attempts=r.attempts,valid=attempts.filter(a=>a.final_score!==null),avg=valid.length?valid.reduce((sum,a)=>sum+Number(a.final_score),0)/valid.length:null;
 v.innerHTML=`<div class="stats"><div class="stat">Số lượt tham gia<b>${attempts.length}</b></div><div class="stat">Đã nộp<b>${attempts.filter(a=>a.status==='submitted').length}</b></div><div class="stat">Điểm TB (đã chấm hết)<b>${avg===null?'—':avg.toFixed(2)}</b></div></div><div class="row" style="margin:15px 0"><button class="primary" id="exportExcel">Xuất Excel .xlsx</button></div><div class="tablewrap"><table><thead><tr><th>Họ tên</th><th>Lớp</th><th>Thời điểm nộp</th><th>Điểm tạm tính</th><th>Điểm chính thức</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${E(a.student_name)}</td><td>${E(a.student_class)}</td><td>${a.submitted_at?E(new Date(a.submitted_at).toLocaleString('vi-VN')):'Chưa nộp'}</td><td>${a.auto_score??'—'}</td><td>${a.final_score??'Chờ chấm'}</td><td>${a.status==='submitted'?'Đã nộp':'Đang làm'}</td><td><button data-inspect="${a.id}">Chi tiết / chấm</button></td></tr>`).join('')}</tbody></table></div><div id="inspect"></div>`;
 $('exportExcel').onclick=exportExcel;v.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspectAttempt(b.dataset.inspect));
}
function inspectAttempt(id){const a=state.report.attempts.find(a=>a.id===id),qs=state.report.questions;const area=$('inspect');if(!a)return;
 area.innerHTML=`<hr class="sep"><h3>Bài làm: ${E(a.student_name)} · ${E(a.student_class)}</h3><div class="list">${qs.map((q,i)=>{const answer=a.answers?.[q.id],detail=a.grading_details?.details?.find(x=>x.question_id===q.id);return `<details><summary>PHẦN ${E(q.section)} - Câu ${i+1} · ${E(label[q.type])} · ${detail?.score??'Chờ chấm'} / ${E(q.points)} điểm</summary>${qHTML(q,true)}<div class="subtle"><b>Học sinh trả lời:</b><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${E(answer===undefined?'(chưa trả lời)':typeof answer==='object'?JSON.stringify(answer):answer)}</pre></div>${q.type==='essay'?`<label class="field">Chấm tự luận (0 đến ${E(q.points)} điểm)</label><input type="number" min="0" max="${E(q.points)}" step="0.01" data-mark="${q.id}" value="${detail?.status==='teacher_graded'?E(detail.score):''}">`:''}</details>`}).join('')}</div><label class="field">Nhận xét giáo viên</label><textarea id="teacherNotes">${E(a.teacher_notes||'')}</textarea><button class="primary" id="saveMarks" ${a.status!=='submitted'?'disabled':''}>LƯU ĐIỂM TỰ LUẬN</button>`;
 $('saveMarks').onclick=async()=>{const marks={};area.querySelectorAll('[data-mark]').forEach(x=>{if(x.value!=='')marks[x.dataset.mark]=+x.value});try{await API.call('teacher.essay',{attempt_id:a.id,marks,notes:$('teacherNotes').value},true);toast('Đã lưu điểm trên máy chủ');state.report=await API.call('teacher.results',{room_id:state.selectedRoom},true);drawResults()}catch(e){err(e)}};
}
function xml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
async function xlsxFromRows(rows){const z=new JSZip();z.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
 z.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
 z.file('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Bang diem" sheetId="1" r:id="rId1"/></sheets></workbook>');
 z.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');
 let body='';rows.forEach((row,i)=>{body+=`<row r="${i+1}">`;row.forEach((v,j)=>{let col='',k=j+1;while(k){k--;col=String.fromCharCode(65+k%26)+col;k=Math.floor(k/26)}const cell=col+(i+1);body+=typeof v==='number'&&Number.isFinite(v)?`<c r="${cell}"><v>${v}</v></c>`:`<c r="${cell}" t="inlineStr"><is><t>${xml(v)}</t></is></c>`});body+='</row>'});
 z.file('xl/worksheets/sheet1.xml','<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+body+'</sheetData></worksheet>');return z.generateAsync({type:'blob',compression:'DEFLATE'});
}
async function exportExcel(){try{const r=state.report,rows=[['STT','Họ tên','Lớp','Bắt đầu','Thời gian nộp','Trạng thái','Điểm tự động','Điểm chính thức','Câu đúng','Câu sai','Chưa trả lời','Còn chấm tự luận','Ghi chú']];
 r.attempts.forEach((a,i)=>rows.push([i+1,a.student_name,a.student_class,a.started_at,a.submitted_at||'',a.status,a.auto_score??'',a.final_score??'',a.grading_details?.correct??'',a.grading_details?.incorrect??'',a.grading_details?.unanswered??'',a.grading_details?.pending??'',a.teacher_notes||'']));
 const blob=await xlsxFromRows(rows),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download='Bang_diem_'+r.room.code+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('Đã xuất Excel')
 }catch(e){err(e)}}
function student(){if(state.student){studentExam();return}
 const code=new URLSearchParams(location.search).get('room')||'';
 root.innerHTML=`<div class="card" style="max-width:650px;margin:22px auto"><h2>HỌC SINH – THAM GIA PHÒNG THI</h2><p class="muted">Nhập mã phòng do giáo viên cung cấp. Em cần điền đúng họ tên và lớp.</p><label class="field">Mã phòng</label><input id="studentCode" value="${E(code)}" maxlength="16" placeholder="Mã phòng thi"><div class="row" style="margin:12px 0"><button id="checkRoom">KIỂM TRA PHÒNG</button><button id="resumeExam">KHÔI PHỤC BÀI ĐANG LÀM</button></div><div id="roomInfo"></div><label class="field">Họ tên học sinh *</label><input id="studentName" autocomplete="name"><label class="field">Lớp *</label><input id="studentClass"><button class="primary wide" id="joinRoom" style="margin-top:15px">BẮT ĐẦU LÀM BÀI</button></div>`;
 $('checkRoom').onclick=async()=>{try{const r=await API.call('student.room',{code:$('studentCode').value});$('roomInfo').innerHTML=`<div class="good"><b>${E(r.exam.title)}</b><div>Môn ${E(r.exam.subject)} · ${r.room.duration_minutes} phút</div><div>Thời hạn mở phòng: ${E(new Date(r.room.ends_at).toLocaleString('vi-VN'))}</div></div>`}catch(e){err(e)}};
 $('joinRoom').onclick=async()=>{if(!$('studentName').value.trim()||!$('studentClass').value.trim())return toast('Cần nhập họ tên và lớp',true);
  try{const code=$('studentCode').value.trim().toUpperCase(),result=await API.call('student.join',{code,name:$('studentName').value,className:$('studentClass').value});
    state.student={token:result.token,code,name:$('studentName').value,className:$('studentClass').value};state.answers={};state.current=0;state.deadline=Date.parse(result.deadline_at);state.offset=Date.parse(result.server_time)-Date.now();state.questions=result.questions;localStorage.setItem('a4_active_attempt',JSON.stringify(state.student));cacheAnswers();studentExam();
  }catch(e){err(e)}};
 $('resumeExam').onclick=resumeAttempt;
 if(code)$('checkRoom').click();
}
function cacheAnswers(){try{localStorage.setItem('a4_student_'+state.student.token,JSON.stringify({answers:state.answers,marked:state.marked,current:state.current}))}catch{}}
async function resumeAttempt(){try{const s=JSON.parse(localStorage.getItem('a4_active_attempt')||'null');if(!s?.token)throw Error('Trình duyệt này chưa lưu phiên thi');
 const r=await API.call('student.resume',{token:s.token});
 if(r.submitted){localStorage.removeItem('a4_active_attempt');state.student=null;showSubmitted();return}
 state.student=s;state.questions=r.questions;state.deadline=Date.parse(r.deadline_at);state.offset=Date.parse(r.server_time)-Date.now();const cache=JSON.parse(localStorage.getItem('a4_student_'+s.token)||'{}');state.answers=cache.answers||r.answers||{};state.marked=cache.marked||{};state.current=cache.current||0;studentExam();toast('Đã khôi phục bài làm')
 }catch(e){err(e)}}
function answered(q){const x=state.answers[q.id];return x!==undefined&&x!==null&&x!==''&&(q.type!=='tf'||Object.keys(x||{}).length>0)}
function studentExam(){const qs=state.questions,q=qs[state.current];if(!q)return toast('Không có dữ liệu câu hỏi',true);
 root.innerHTML=`<div class="row between" style="margin-bottom:13px"><div><b>${E(state.student.name)} · ${E(state.student.className)}</b><div class="tiny">Mã phòng: ${E(state.student.code)}</div></div><div><div id="clock"></div><div id="saveState" class="tiny">Tự động lưu bài</div></div></div><div class="columns"><div class="card"><div class="row between"><h2>PHẦN ${E(q.section)} – Câu ${E(q.number||state.current+1)}</h2><span class="pill">${state.current+1}/${qs.length}</span></div>${qHTML({id:q.id,section:q.section,position:q.position,number:q.number||state.current+1,body:q.body,type:q.type,media:q.media,options:[],statements:[]})}<div id="answerArea">${studentAnswerHTML(q)}</div><div class="row" style="margin:18px 0"><label><input id="markThis" type="checkbox" ${state.marked[q.id]?'checked':''}> Đánh dấu xem lại</label></div><div class="row between"><button id="studentPrev" ${state.current===0?'disabled':''}>← Câu trước</button><button id="studentNext" ${state.current===qs.length-1?'disabled':''}>Câu tiếp →</button></div><hr class="sep"><button class="primary" id="submitExam">NỘP BÀI</button></div><aside><div class="card"><h3>Danh sách câu hỏi</h3><div class="quiz-nav">${qs.map((x,i)=>`<button class="q-number ${i===state.current?'active':''} ${answered(x)?'done':''} ${state.marked[x.id]?'marked':''}" data-sq="${i}">${i+1}</button>`).join('')}</div><p class="tiny">Xanh lá: đã trả lời · Viền vàng: cần xem lại</p><p>Đã làm: ${qs.filter(answered).length}/${qs.length}</p></div></aside></div>`;
 $('studentPrev').onclick=()=>moveStudent(-1);$('studentNext').onclick=()=>moveStudent(1);root.querySelectorAll('[data-sq]').forEach(b=>b.onclick=()=>moveStudent(+b.dataset.sq-state.current));
 $('markThis').onchange=e=>{state.marked[q.id]=e.target.checked;cacheAnswers();studentExam()};$('submitExam').onclick=submitExam;
 root.querySelectorAll('[data-answer]').forEach(b=>b.onchange=()=>{readAnswer(q);cacheAnswers();scheduleSave();drawStudentNav()});
 root.querySelectorAll('textarea[data-essay],input[data-short]').forEach(b=>b.oninput=()=>{readAnswer(q);cacheAnswers();scheduleSave();const e=$('saveState');if(e)e.textContent='Đang chờ lưu lên máy chủ'});
 timer();renderMath();
}
function studentAnswerHTML(q){const a=state.answers[q.id];if(q.type==='mcq')return (q.options||[]).map(o=>`<label class="option ${a===o.id?'answer':''}"><input type="radio" data-answer="mcq" name="mcq" value="${E(o.id)}" ${a===o.id?'checked':''}><div><b>${E(o.id)}.</b> ${E(o.text)}${mediaHTML(o.media)}</div></label>`).join('');
 if(q.type==='tf')return (q.statements||[]).map(s=>`<div class="option"><div style="flex:1"><b>${E(s.id)})</b> ${E(s.text)}${mediaHTML(s.media)}</div><select data-answer="tf" data-tfid="${E(s.id)}" style="width:115px"><option value="">-- Chọn --</option><option value="true" ${a?.[s.id]===true?'selected':''}>Đúng</option><option value="false" ${a?.[s.id]===false?'selected':''}>Sai</option></select></div>`).join('');
 if(q.type==='short')return `<label class="field">Nhập đáp án (trả lời ngắn)</label><input data-short placeholder="Nhập đáp án" value="${E(a??'')}">`;
 return `<label class="field">Bài làm tự luận</label><textarea data-essay rows="11" placeholder="Nhập nội dung bài giải">${E(a??'')}</textarea>`;
}
function readAnswer(q){if(q.type==='mcq')state.answers[q.id]=root.querySelector('[data-answer="mcq"]:checked')?.value||null;
 if(q.type==='tf'){state.answers[q.id]={};root.querySelectorAll('[data-tfid]').forEach(x=>{if(x.value)state.answers[q.id][x.dataset.tfid]=x.value==='true'})}
 if(q.type==='short')state.answers[q.id]=root.querySelector('[data-short]').value;
 if(q.type==='essay')state.answers[q.id]=root.querySelector('[data-essay]').value;
}
function drawStudentNav(){const qs=state.questions;root.querySelectorAll('[data-sq]').forEach(b=>{b.classList.toggle('done',answered(qs[+b.dataset.sq]));b.classList.toggle('marked',!!state.marked[qs[+b.dataset.sq].id])})}
function moveStudent(d){state.current=Math.max(0,Math.min(state.questions.length-1,state.current+d));cacheAnswers();studentExam()}
let saveTimer=null;
function scheduleSave(){state.studentSaved=false;clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveStudent(),1400)}
async function saveStudent(){if(!state.student)return;try{const r=await API.call('student.save',{token:state.student.token,answers:state.answers});state.studentSaved=true;const v=$('saveState');if(v)v.textContent='Đã lưu trên máy chủ';if(r.submitted)finishStudent();}catch(e){const v=$('saveState');if(v)v.textContent='Mất kết nối: đã lưu tạm trên máy này';console.warn(e.message)}}
let clockInterval=null;
function timer(){clearInterval(clockInterval);const tick=()=>{if(!state.student)return;const remain=Math.max(0,state.deadline-(Date.now()+state.offset));const s=Math.floor(remain/1000),el=$('clock');if(el)el.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
 if(remain<=0){clearInterval(clockInterval);submitExam(true)}};tick();clockInterval=setInterval(tick,1000)}
async function submitExam(auto=false){if(state.submitting||!state.student)return;if(!auto&&!confirm('Xác nhận NỘP BÀI? Sau khi nộp không thể sửa câu trả lời.'))return;
 state.submitting=true;clearTimeout(saveTimer);try{const s=await API.call('student.submit',{token:state.student.token,answers:state.answers});if(s.ok)finishStudent();else throw Error('Máy chủ chưa xác nhận nộp bài');
 }catch(e){state.submitting=false;cacheAnswers();err(e);if(auto)root.insertAdjacentHTML('afterbegin','<div class="error">Chưa thể nộp do mất kết nối. Bài được lưu tạm trên máy; hãy kết nối lại và nộp ngay. Điểm sẽ phụ thuộc thời điểm máy chủ nhận bài.</div>')}
}
function finishStudent(){clearInterval(clockInterval);localStorage.removeItem('a4_active_attempt');state.student=null;state.questions=[];state.answers={};state.submitting=false;showSubmitted()}
function showSubmitted(){root.innerHTML=`<div class="card" style="max-width:650px;margin:55px auto;text-align:center;padding:55px 20px"><h2 style="color:#18704b">ĐÃ NỘP BÀI THÀNH CÔNG!</h2><p>Bài làm của em đã được ghi nhận.</p><p class="tiny">Thông tin về điểm số, đáp án và lời giải không được công bố trong chế độ học sinh.</p><button data-go="home">VỀ TRANG CHỦ</button></div>`;}
window.addEventListener('online',()=>{if(state.student&&!state.submitting)saveStudent()});
function help(){root.innerHTML=`<div class="card"><h2>HƯỚNG DẪN SỬ DỤNG TỪNG CHỨC NĂNG</h2><details open><summary>1. Kết nối Supabase</summary><p>Tạo dự án Supabase, thực thi migration SQL, triển khai Edge Function <code>exam-api</code>, cấu hình biến môi trường cho backend. Vào tab Kết nối, điền Project URL và publishable key rồi kiểm tra kết nối.</p></details><details><summary>2. Tự tạo tài khoản giáo viên</summary><p>Quản trị viên đăng nhập → Mời giáo viên, nhập email được phép → Sao chép link đăng ký. Giáo viên chọn TẠO TÀI KHOẢN, đăng ký đúng email và xác nhận email Supabase. Hệ thống tự cấp quyền teacher sau xác minh. Mỗi giáo viên chỉ quản lý đề, phòng thi và kết quả của mình. Người không có lời mời ở trạng thái chờ.</p></details><details><summary>3. Nhập đề gốc Word</summary><p>Chọn Giáo viên → Nhập & duyệt Word → chọn .docx. Phần I tìm phương án có chữ đỏ. Phần II đọc màu chữ của các ý a, b, c, d. Phần III đọc dòng <b>Đáp án:</b>. Nếu gặp ảnh WMF, các biểu thức lạ hay thiếu hình, hệ thống gắn cảnh báo.</p></details><details><summary>4. Duyệt đề và biểu điểm</summary><p>Mở lần lượt từng câu, kiểm tra với file Word gốc, bổ sung ảnh PNG/JPEG nếu cần, nhập điểm và quy tắc chấm từng câu. Tích xác nhận chỉ khi câu đã đúng và xử lý hết cảnh báo. Lưu đề vào ngân hàng.</p></details><details><summary>5. Tạo phòng thi và chia sẻ</summary><p>Chọn đề đã lưu, đặt thời điểm bắt đầu/kết thúc mở phòng và số phút làm bài. Hệ thống kiểm tra toàn bộ câu đã được duyệt, rồi mới phát hành. Chia sẻ mã phòng, link hoặc QR từ trang Phòng thi.</p></details><details><summary>6. Học sinh tham gia và nộp bài</summary><p>Học sinh mở link/mã phòng, nhập họ tên, lớp, làm bài. Câu trả lời lưu tự động lên máy chủ và bản tạm trên máy. Sau khi nộp chỉ hiện xác nhận nộp bài.</p></details><details><summary>7. Chấm bài và xuất Excel</summary><p>Giáo viên mở Bảng điểm, chọn phòng. Xem câu trả lời và điểm tự động; nhập điểm tự luận; tải bảng điểm Excel. Điểm chính thức chỉ hiện sau khi tất cả câu tự luận được chấm.</p></details><div class="warning">Mọi tài khoản, đề, điểm và bài làm là dữ liệu thật khi đã kết nối backend. Nên thử nghiệm với nhóm nhỏ trước khi tổ chức thi chính thức. Bảo mật, giới hạn truy cập và sao lưu cần cấu hình phù hợp.</div></div>`;}
function render(){if(state.route==='home')home();else if(state.route==='config')config();else if(state.route==='teacher')teacher();else if(state.route==='offlineEditor')localEditor();else if(state.route==='student')student();else if(state.route==='resetPassword')resetPassword();else if(state.route==='help')help();renderMath()}
document.body.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-route]');if(b){const next=b.dataset.go||b.dataset.route;if(next==='offlineEditor')return;route(next)}});
loadDraft();const authRedirect=API.consumeAuthRedirect();if(authRedirect==='recovery')route('resetPassword');else if(new URLSearchParams(location.search).has('room'))route('student');else if(new URLSearchParams(location.search).get('teacher')==='register'){state.authMode='signup';route('teacher')}else if(authRedirect)route('teacher');else render();
window.A4_DEBUG={getState:()=>state,readWord:f=>WordReader.readWord(f),gradeXMLRows:xlsxFromRows};
})();
